<?php

namespace Database\Factories;

use App\Enums\Discipline;
use App\Enums\TournamentFormat;
use App\Enums\TournamentStatus;
use App\Models\Tournament;
use App\Models\TournamentEntry;
use App\Models\User;
use Carbon\CarbonImmutable;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * Tournaments without entries or a draw by default (a singles knockout, registration open).
 * Use withEntries() for registrations; draws are generated by App\Services\Tournament\DrawGenerator.
 *
 * @extends Factory<Tournament>
 */
class TournamentFactory extends Factory
{
    /**
     * @var class-string<Tournament>
     */
    protected $model = Tournament::class;

    private const NAME_PREFIXES = [
        'Autumn', 'Winter', 'Spring', 'Summer', 'Campus', 'Breda', 'Mollengracht', 'Night Owl', 'Freshers', 'Committee',
    ];

    private const NAME_SUFFIXES = [
        'Open', 'Cup', 'Classic', 'Challenge', 'Showdown', 'Smash', 'Masters', 'Trophy',
    ];

    private const DESCRIPTIONS = [
        'A friendly one-day tournament for every level. Matches are best of three games to 21.',
        'Seeded by rating, so the strongest players meet in the later rounds. Results count towards your rating.',
        'Sign up early: places are limited and the draw is made once registration closes.',
        'Bring indoor shoes and a water bottle. Shuttles are provided by the club.',
    ];

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        $startsAt = $this->day(fake()->numberBetween(14, 60));

        return [
            'name' => fake()->randomElement(self::NAME_PREFIXES).' '.fake()->randomElement(self::NAME_SUFFIXES),
            'description' => fake()->randomElement(self::DESCRIPTIONS),
            'discipline' => Discipline::Singles,
            'format' => TournamentFormat::SingleElimination,
            'status' => TournamentStatus::Open,
            'venue' => config('smash.club.venue'),
            'starts_at' => $startsAt,
            'ends_at' => $startsAt->setTime(18, 0),
            'registration_closes_at' => $startsAt->subDays(2)->setTime(23, 59),
            'max_entries' => 16,
            'best_of' => 3,
            'points_per_game' => 21,
            'is_rated' => true,
            'created_by' => null,
        ];
    }

    /**
     * Registration open, starting in a few weeks.
     */
    public function open(): static
    {
        return $this->upcomingWith(TournamentStatus::Open);
    }

    /**
     * Being prepared by the committee; hidden from members.
     */
    public function draft(): static
    {
        return $this->upcomingWith(TournamentStatus::Draft);
    }

    /**
     * Draw made and matches being played (started yesterday).
     */
    public function inProgress(): static
    {
        return $this->state(function (array $attributes) {
            $startsAt = $this->day(-1);

            return [
                'status' => TournamentStatus::InProgress,
                'starts_at' => $startsAt,
                'ends_at' => $startsAt->addDays(7)->setTime(18, 0),
                'registration_closes_at' => $startsAt->subDays(2)->setTime(23, 59),
            ];
        });
    }

    /**
     * Played and finished some weeks ago.
     */
    public function completed(): static
    {
        return $this->state(function (array $attributes) {
            $startsAt = $this->day(-fake()->numberBetween(14, 60));

            return [
                'status' => TournamentStatus::Completed,
                'starts_at' => $startsAt,
                'ends_at' => $startsAt->setTime(18, 0),
                'registration_closes_at' => $startsAt->subDays(2)->setTime(23, 59),
            ];
        });
    }

    public function singles(): static
    {
        return $this->state(fn (array $attributes) => [
            'discipline' => Discipline::Singles,
        ]);
    }

    public function doubles(): static
    {
        return $this->state(fn (array $attributes) => [
            'discipline' => Discipline::Doubles,
        ]);
    }

    /**
     * Single elimination.
     */
    public function knockout(): static
    {
        return $this->state(fn (array $attributes) => [
            'format' => TournamentFormat::SingleElimination,
        ]);
    }

    public function roundRobin(): static
    {
        return $this->state(fn (array $attributes) => [
            'format' => TournamentFormat::RoundRobin,
        ]);
    }

    /**
     * Still "open", but the registration deadline has passed.
     */
    public function registrationClosed(): static
    {
        return $this->state(fn (array $attributes) => [
            'registration_closes_at' => CarbonImmutable::instance(now())->subDay(),
        ]);
    }

    /**
     * Maximum number of entries (null = unlimited).
     */
    public function maxEntries(?int $maxEntries): static
    {
        return $this->state(fn (array $attributes) => [
            'max_entries' => $maxEntries,
        ]);
    }

    public function unrated(): static
    {
        return $this->state(fn (array $attributes) => [
            'is_rated' => false,
        ]);
    }

    /**
     * Register $count new players (pairs for doubles) after creating the tournament.
     */
    public function withEntries(int $count): static
    {
        return $this->afterCreating(function (Tournament $tournament) use ($count): void {
            TournamentEntry::factory()
                ->count($count)
                ->for($tournament)
                ->state(fn (array $attributes) => [
                    'partner_id' => $tournament->isDoubles() ? User::factory() : null,
                ])
                ->create();
        });
    }

    private function upcomingWith(TournamentStatus $status): static
    {
        return $this->state(function (array $attributes) use ($status) {
            $startsAt = $this->day(fake()->numberBetween(14, 60));

            return [
                'status' => $status,
                'starts_at' => $startsAt,
                'ends_at' => $startsAt->setTime(18, 0),
                'registration_closes_at' => $startsAt->subDays(2)->setTime(23, 59),
            ];
        });
    }

    /**
     * 10:00 on the day $days from today (negative = in the past).
     */
    private function day(int $days): CarbonImmutable
    {
        return CarbonImmutable::instance(now())->addDays($days)->setTime(10, 0);
    }
}
